// Test Harness for Chess Roulette App
// Provides direct access to app state for fast verification (~5ms calls)
// Only active in development mode

declare global {
  interface Window {
    __TEST_API__?: {
      _meta: {
        name: string;
        framework: string;
        stateLib: string;
        createdBy: string;
      };
      actions: Record<string, (...args: any[]) => any>;
      queries: Record<string, (...args: any[]) => any>;
    };
  }
}

// This file will be imported in the App entry point
// It exposes semantic actions and queries for testing the chess-roulette app

if (import.meta.env.DEV) {
  window.__TEST_API__ = {
    _meta: {
      name: 'Chess Roulette',
      framework: 'react',
      stateLib: 'context',
      createdBy: 'fabric-agent',
    },
    actions: {
      // Connection actions
      connect: async () => {
        const { socketService } = await import('../services/socket');
        await socketService.connect();
      },

      disconnect: async () => {
        const { socketService } = await import('../services/socket');
        socketService.disconnect();
      },

      // Queue actions
      joinQueue: () => {
        const { socketService } = require('../services/socket');
        socketService.joinQueue();
      },

      leaveQueue: () => {
        const { socketService } = require('../services/socket');
        socketService.leaveQueue();
      },

      // Game actions
      makeMove: (from: string, to: string) => {
        const { socketService } = require('../services/socket');
        const { Chess } = require('chess.js');
        const chess = new Chess();
        const move = chess.move({ from, to, promotion: 'q' });
        if (move) {
          socketService.makeMove('test-game', move.san, chess.fen());
        }
      },

      resign: (gameId: string) => {
        const { socketService } = require('../services/socket');
        socketService.resign(gameId);
      },

      // Chat actions
