        const { socketService } = require('../services/socket');
        socketService.sendChatMessage(gameId, message);
      },

      // Video actions
      toggleVideo: (enabled: boolean) => {
        const { webRTCService } = require('../services/webrtc');
        webRTCService.toggleVideo(enabled);
      },

      toggleAudio: (enabled: boolean) => {
        const { webRTCService } = require('../services/webrtc');
        webRTCService.toggleAudio(enabled);
      },

      switchCamera: async () => {
        const { webRTCService } = require('../services/webrtc');
        await webRTCService.switchCamera();
      },

      // DOM actions (using page API when available)
      clickElement: async (selector: string) => {
        if (window.page) {
          await window.page.click(selector);
        }
      },

      fillInput: async (selector: string, value: string) => {
        if (window.page) {
          await window.page.fill(selector, value);
        }
      },
    },
    queries: {
      // Connection state
      isConnected: () => {
        const { socketService } = require('../services/socket');
        return socketService.isConnected();
      },

      getSocketId: () => {
        const { socketService } = require('../services/socket');
        return socketService.getId();
      },

      // Game state queries (would need access to context)
      // These are placeholders - actual implementation requires context access
      getGameState: () => {
        // Would need to access GameContext state
        return null;
      },

      isQueued: () => false,
      isMatched: () => false,
      isPlaying: () => false,
      getFEN: () => 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
      isMyTurn: () => true,
      getGameStatus: () => 'waiting',

      // DOM queries
      getBoardOrientation: () => 'white',
      getTurnIndicator: () => {
        if (window.page) {
          return window.page.textContent('[data-testid="turn-indicator"]');
        }
        return null;
      },

      getStatusMessage: () => {
        if (window.page) {
          return window.page.textContent('[data-testid="status-message"]');
        }
        return null;
      },

      getChatMessages: () => {
        if (window.page) {
          return window.page.evaluate(() => {
            return Array.from(document.querySelectorAll('[data-testid="chat-message"]')).map(
              (el) => el.textContent
            );
          });
        }
        return [];
      },

      getVideoStatus: (isLocal: boolean) => {
        if (window.page) {
          return window.page.isVisible(`[data-testid="${isLocal ? 'local' : 'remote'}-video"]`);
        }
        return false;
      },

      // Chess board queries
      getBoardPosition: () => {
        // Return current FEN position
        const { Chess } = require('chess.js');
        const chess = new Chess();
        return chess.fen();
      },

      isValidMove: (from: string, to: string) => {
        const { Chess } = require('chess.js');
        const chess = new Chess();
        try {
          const move = chess.move({ from, to, promotion: 'q' });
          return !!move;
        } catch {
          return false;
        }
      },

      getLegalMoves: (square: string) => {
        const { Chess } = require('chess.js');
