        const { Chess } = require('chess.js');
        const chess = new Chess();
        return chess.isDraw();
      },

      isStalemate: () => {
        const { Chess } = require('chess.js');
        const chess = new Chess();
        return chess.isStalemate();
      },
    },
  };
}

