import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
import { Chess } from 'chess.js';

describe('Chess Logic Tests', () => {
  let chess: Chess;

  beforeEach(() => {
    chess = new Chess();
  });

  afterEach(() => {
    chess = new Chess();
  });

  describe('Initial State', () => {
    it('should start with standard chess position', () => {
      expect(chess.fen()).toBe('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1');
    });

    it('should have white to move first', () => {
      expect(chess.turn()).toBe('w');
    });

    it('should not be in check at start', () => {
      expect(chess.inCheck()).toBe(false);
    });

    it('should not be game over at start', () => {
      expect(chess.isGameOver()).toBe(false);
    });
  });

  describe('Valid Moves', () => {
    it('should allow pawn to move forward one square', () => {
      const move = chess.move({ from: 'e2', to: 'e3', promotion: 'q' });
      expect(move).toBeTruthy();
      expect(chess.fen()).toContain('P');
    });

    it('should allow pawn to move forward two squares on first move', () => {
      const move = chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      expect(move).toBeTruthy();
      expect(move.san).toBe('e4');
    });

    it('should allow knight to move in L-shape', () => {
      const move = chess.move({ from: 'g1', to: 'f3', promotion: 'q' });
      expect(move).toBeTruthy();
      expect(move.san).toBe('Nf3');
    });

    it('should allow multiple moves in sequence', () => {
      chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      chess.move({ from: 'e7', to: 'e5', promotion: 'q' });
      chess.move({ from: 'g1', to: 'f3', promotion: 'q' });
      chess.move({ from: 'b8', to: 'c6', promotion: 'q' });

      expect(chess.history().length).toBe(4);
    });
  });

  describe('Invalid Moves', () => {
    it('should not allow pawn to move backward', () => {
      expect(() => chess.move({ from: 'e2', to: 'e1', promotion: 'q' })).toThrow();
    });

    it('should not allow pawn to move two squares diagonally', () => {
      expect(() => chess.move({ from: 'e2', to: 'd4', promotion: 'q' })).toThrow();
    });

    it('should not allow knight to move in straight line', () => {
      expect(() => chess.move({ from: 'g1', to: 'g3', promotion: 'q' })).toThrow();
    });

    it('should not allow moving opponent pieces', () => {
      expect(() => chess.move({ from: 'e7', to: 'e5', promotion: 'q' })).toThrow();
    });

    it('should not allow moving to square occupied by own piece', () => {
      expect(() => chess.move({ from: 'e2', to: 'e1', promotion: 'q' })).toThrow();
    });
  });

  describe('Special Moves', () => {
    it('should handle castling kingside', () => {
      // Setup castling position
      chess.load('r3kbnr/pppppppp/8/8/8/8/PPPPPPPP/R3KBNR w KQkq - 0 1');
      const move = chess.move({ from: 'e1', to: 'g1', promotion: 'q' });
      expect(move.san).toBe('O-O');
    });

    it('should handle castling queenside', () => {
      // Setup castling position
      chess.load('r3kbnr/pppppppp/8/8/8/8/PPPPPPPP/R3KBNR w Qkq - 0 1');
      const move = chess.move({ from: 'e1', to: 'c1', promotion: 'q' });
      expect(move.san).toBe('O-O-O');
    });

    it('should handle en passant capture', () => {
      chess.load('5k2/8/8/8/5Pp1/8/8/4K3 w - - 0 1');
      chess.move({ from: 'f4', to: 'f5', promotion: 'q' });
      const move = chess.move({ from: 'g4', to: 'f3', promotion: 'q' });
      expect(move.san).toBe('gxf3');
      expect(move.flags).toContain('e'); // en passant flag
    });

    it('should handle pawn promotion to queen', () => {
      chess.load('8/P7/8/8/8/8/8/4K3 w - - 0 1');
      const move = chess.move({ from: 'a7', to: 'a8', promotion: 'q' });
      expect(move.san).toBe('a8=Q');
      expect(move.promotion).toBe('q');
    });

    it('should handle pawn promotion to other pieces', () => {
      chess.load('8/P7/8/8/8/8/8/4K3 w - - 0 1');
      const move = chess.move({ from: 'a7', to: 'a8', promotion: 'n' });
      expect(move.promotion).toBe('n');
    });
  });

  describe('Game End Conditions', () => {
    it('should detect checkmate', () => {
      chess.load('rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR w KQkq - 1 3');
      expect(chess.isCheckmate()).toBe(true);
      expect(chess.isGameOver()).toBe(true);
    });

    it('should detect stalemate', () => {
      chess.load('k7/8/2K5/8/8/8/8/8 w - - 0 1');
      expect(chess.isStalemate()).toBe(true);
      expect(chess.isGameOver()).toBe(true);
    });

    it('should detect draw by insufficient material', () => {
      chess.load('k7/8/8/8/8/8/8/4K3 w - - 0 1');
      expect(chess.isDraw()).toBe(true);
    });

    it('should detect threefold repetition', () => {
      const moves = [
        { from: 'g1', to: 'f3' },
        { from: 'b8', to: 'c6' },
        { from: 'f3', to: 'g1' },
        { from: 'c6', to: 'b8' },
        { from: 'g1', to: 'f3' },
        { from: 'b8', to: 'c6' },
        { from: 'f3', to: 'g1' },
        { from: 'c6', to: 'b8' },
      ];

      moves.forEach((move) => {
        chess.move(move);
      });

      expect(chess.isThreefoldRepetition()).toBe(true);
    });

    it('should detect fifty move rule', () => {
      chess.load('k7/8/8/8/8/8/8/4K3 w - - 98 50');
      // After 50 moves without pawn move or capture
      expect(chess.isFiftyMoves()).toBe(true);
    });
  });

  describe('Move History', () => {
    it('should track move history in SAN notation', () => {
      chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      chess.move({ from: 'e7', to: 'e5', promotion: 'q' });
      chess.move({ from: 'g1', to: 'f3', promotion: 'q' });

      const history = chess.history();
      expect(history).toEqual(['e4', 'e5', 'Nf3']);
    });

    it('should track move history with verbose details', () => {
      chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      const verbose = chess.history({ verbose: true });

      expect(verbose[0]).toMatchObject({
        from: 'e2',
        to: 'e4',
        san: 'e4',
        color: 'w',
      });
    });

    it('should undo moves', () => {
      chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      chess.move({ from: 'e7', to: 'e5', promotion: 'q' });

      const undone = chess.undo();
      expect(undone).toBeTruthy();
      expect(chess.history()).toEqual(['e4']);
    });
  });

  describe('Board State', () => {
    it('should get piece positions', () => {
      const board = chess.board();
      expect(board[0][0]).toEqual({ type: 'r', color: 'b' }); // Black rook on a8
      expect(board[1][1]).toEqual({ type: 'p', color: 'b' }); // Black pawn on b7
      expect(board[6][6]).toEqual({ type: 'p', color: 'w' }); // White pawn on g2
      expect(board[7][7]).toEqual({ type: 'r', color: 'w' }); // White rook on h1
    });

    it('should get all pieces', () => {
      const pieces = chess.pieces();
      expect(pieces).toBe(32); // Starting position has 32 pieces
    });

    it('should detect if square is attacked', () => {
      chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      // e4 should be attacked by black pawns
      expect(chess.isAttacked('e4', 'b')).toBe(true);
    });
  });

  describe('FEN and PGN', () => {
    it('should generate valid FEN', () => {
      const fen = chess.fen();
      expect(fen).toMatch(/^[bnrqkpPNRQKB\/1-8]+ [wb] [KQkq-]+ [0-9a-f-]+ \d+ \d+$/);
    });

    it('should load valid FEN', () => {
      const newFen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1';
      chess.load(newFen);
      expect(chess.fen()).toBe(newFen);
    });

    it('should generate PGN', () => {
      chess.move({ from: 'e2', to: 'e4', promotion: 'q' });
      chess.move({ from: 'e7', to: 'e5', promotion: 'q' });
      chess.move({ from: 'g1', to: 'f3', promotion: 'q' });

      const pgn = chess.pgn();
      expect(pgn).toContain('1. e4 e5 2. Nf3');
    });
  });

  describe('Legal Moves', () => {
    it('should get all legal moves from starting position', () => {
      const moves = chess.moves();
      expect(moves.length).toBe(20); // 16 pawn moves + 4 knight moves
    });

    it('should get legal moves for specific square', () => {
      const moves = chess.moves({ square: 'e2' });
      expect(moves).toContain('e3');
      expect(moves).toContain('e4');
    });

    it('should return empty array when no legal moves', () => {
      chess.load('k7/8/2K5/8/8/8/8/8 w - - 0 1'); // Stalemate
      const moves = chess.moves();
      expect(moves).toEqual([]);
    });
  });

  describe('Check and Checkmate', () => {
    it('should detect when king is in check', () => {
      chess.load('rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR w KQkq - 1 3');
      expect(chess.inCheck()).toBe(true);
    });

    it('should not detect check when king is safe', () => {
      expect(chess.inCheck()).toBe(false);
    });

    it('should identify checkmate winner', () => {
      chess.load('rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR w KQkq - 1 3');
      expect(chess.turn()).toBe('w');
      // White is in checkmate, so black wins
    });
  });
});

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';

// Mock socket.io-client
vi.mock('socket.io-client', () => ({
  io: vi.fn(() => ({
    on: vi.fn((event: string, callback: Function) => {
      if (event === 'connect') {
        setTimeout(() => callback(), 10);
      }
    }),
    off: vi.fn(),
    emit: vi.fn(),
    disconnect: vi.fn(),
    connected: true,
    id: 'test-socket-id',
  })),
}));

import { socketService } from '../services/socket';

describe('SocketService Tests', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    socketService.disconnect();
  });

  describe('Connection', () => {
    it('should connect to server successfully', async () => {
      await expect(socketService.connect()).resolves.toBeUndefined();
      expect(socketService.isConnected()).toBe(true);
    });

    it('should have a socket ID after connection', async () => {
      await socketService.connect();
      expect(socketService.getId()).toBe('test-socket-id');
    });

    it('should disconnect from server', async () => {
      await socketService.connect();
      socketService.disconnect();
      expect(socketService.isConnected()).toBe(false);
      expect(socketService.getId()).toBeUndefined();
    });
  });

  describe('Queue Management', () => {
    it('should emit joinQueue event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      socketService.joinQueue();

      expect(mockSocket.emit).toHaveBeenCalledWith('joinQueue');
    });

    it('should emit leaveQueue event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      socketService.leaveQueue();

      expect(mockSocket.emit).toHaveBeenCalledWith('leaveQueue');
    });
  });

  describe('Game Moves', () => {
    it('should emit makeMove event with correct data', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      socketService.makeMove('game-123', 'e4', 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1');

      expect(mockSocket.emit).toHaveBeenCalledWith('makeMove', {
        gameId: 'game-123',
        move: 'e4',
        fen: 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1',
      });
    });

    it('should emit resign event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      socketService.resign('game-123');

      expect(mockSocket.emit).toHaveBeenCalledWith('resign', { gameId: 'game-123' });
    });
  });

  describe('Chat', () => {
    it('should emit chatMessage event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      socketService.sendChatMessage('game-123', 'Hello opponent!');

      expect(mockSocket.emit).toHaveBeenCalledWith('chatMessage', {
        gameId: 'game-123',
        message: 'Hello opponent!',
      });
    });
  });

  describe('WebRTC Signaling', () => {
    it('should emit webrtc-offer event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      const offer = { type: 'offer', sdp: 'mock-sdp' };
      socketService.sendWebRTCOffer('game-123', offer, 'player-1');

      expect(mockSocket.emit).toHaveBeenCalledWith('webrtc-offer', {
        gameId: 'game-123',
        offer,
        from: 'player-1',
      });
    });

    it('should emit webrtc-answer event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      const answer = { type: 'answer', sdp: 'mock-sdp' };
      socketService.sendWebRTCAnswer('game-123', answer, 'player-2');

      expect(mockSocket.emit).toHaveBeenCalledWith('webrtc-answer', {
        gameId: 'game-123',
        answer,
        from: 'player-2',
      });
    });

    it('should emit webrtc-ice-candidate event', async () => {
      await socketService.connect();
      const mockSocket = (socketService as any).socket;

      const candidate = { candidate: 'mock-candidate', sdpMLineIndex: 0 };
      socketService.sendWebRTCIceCandidate('game-123', candidate, 'player-1');

      expect(mockSocket.emit).toHaveBeenCalledWith('webrtc-ice-candidate', {
        gameId: 'game-123',
        candidate,
        from: 'player-1',
      });
    });
  });

  describe('Event Listeners', () => {
    it('should register event listener', async () => {
      await socketService.connect();
      const mockCallback = vi.fn();

      const unsubscribe = socketService.on('testEvent', mockCallback);

      // Trigger event manually (simulating server event)
      (socketService as any).emit('testEvent', { data: 'test' });

      expect(mockCallback).toHaveBeenCalledWith({ data: 'test' });

      // Cleanup
      unsubscribe();
    });

    it('should remove event listener on unsubscribe', async () => {
      await socketService.connect();
      const mockCallback = vi.fn();

      const unsubscribe = socketService.on('testEvent', mockCallback);
      unsubscribe();

      // Trigger event after unsubscribe
      (socketService as any).emit('testEvent', { data: 'test' });

      expect(mockCallback).not.toHaveBeenCalled();
    });

    it('should handle multiple listeners for same event', async () => {
      await socketService.connect();
      const callback1 = vi.fn();
      const callback2 = vi.fn();

      socketService.on('testEvent', callback1);
      socketService.on('testEvent', callback2);

      (socketService as any).emit('testEvent', { data: 'test' });

      expect(callback1).toHaveBeenCalledWith({ data: 'test' });
      expect(callback2).toHaveBeenCalledWith({ data: 'test' });
    });
  });

  describe('Server Events', () => {
    it('should listen for queueJoined event', async () => {
      await socketService.connect();
      const mockCallback = vi.fn();

      socketService.on('queueJoined', mockCallback);

      // Simulate server sending queueJoined
